import Navbar from "../components/Navbar";
import Leaderboard from "./Leaderboard";
import Footer from "../components/Footer";

export default function UserDash() {
  return (
    <>
      <Navbar isLogin={true} />
         <header style={styles.topbar}>
        <button
          style={styles.menuBtn}
          onClick={() => setSidebarOpen(!sidebarOpen)}
        >
          ☰
        </button>
        <h1 style={styles.logo}>DailyCode</h1>
       <button
  style={styles.logoutBtn}
  onClick={() => {
    localStorage.clear(); // 🔥 sab kuch clear
    navigate("/login", { replace: true }); // 🔥 history reset
    window.location.reload(); // 🔥 React state bhi reset
  }}
>
  Logout
</button>

      </header>


      <div style={{ paddingTop: "90px" }}>
        <Leaderboard />
        <Footer />
      </div>
    </>
  );
}
const styles = {
  app: {
    minHeight: "100vh",
    background: "#0f172a",
    color: "#f1f5f9",
  },
  topbar: {
    height: 60,
    background: "#020617",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "0 20px",
    position: "sticky",
    top: 0,
    zIndex: 50,
  },
  logo: { fontWeight: 700 },
  menuBtn: {
    fontSize: 22,
    background: "none",
    border: "none",
    color: "#f1f5f9",
    cursor: "pointer",
  },
  logoutBtn: {
    background: "#ef4444",
    border: "none",
    color: "#fff",
    padding: "6px 14px",
    borderRadius: 8,
    cursor: "pointer",
  },
  layout: { display: "flex" },
  sidebar: {
    width: 240,
    background: "#020617",
    position: "fixed",
    top: 60,
    bottom: 0,
    left: 0,
    transition: "transform 0.3s ease",
    zIndex: 40,
  },
  nav: {
    display: "flex",
    flexDirection: "column",
    padding: 16,
  },
  navItem: {
    padding: "12px 14px",
    cursor: "pointer",
    borderRadius: 10,
    marginBottom: 6,
    display: "flex",
    alignItems: "center",
  },
};
